export { contentView, panelView, rootView, triggerView } from "../../../foldkit/ui/collapsible";
export type {
  CollapsibleStyle,
  PanelViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../../../foldkit/ui/collapsible";

export {
  shadcnCollapsibleContentClasses,
  shadcnCollapsibleIconClasses,
  shadcnCollapsiblePanelClasses,
  shadcnCollapsibleRootClasses,
  shadcnCollapsibleTriggerClasses,
} from "./view";

export {
  collapsibleContentClasses as shadcnCollapsibleContentClasses,
  collapsibleIconClasses as shadcnCollapsibleIconClasses,
  collapsiblePanelClasses as shadcnCollapsiblePanelClasses,
  collapsibleRootClasses as shadcnCollapsibleRootClasses,
  collapsibleTriggerClasses as shadcnCollapsibleTriggerClasses,
} from "../../../foldkit/ui/collapsible/view";

import { describe, expect, test } from "vitest";

import * as Collapsible from "./index";

describe("shadcn Collapsible registry view", () => {
  test("reuses the Foldkit Collapsible view contract", () => {
    expect(Collapsible.rootView).toBeTypeOf("function");
    expect(Collapsible.triggerView).toBeTypeOf("function");
    expect(Collapsible.panelView).toBeTypeOf("function");
    expect(Collapsible.shadcnCollapsibleTriggerClasses).toContain(
      "font-medium"
    );
  });
});
